INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/jiuwudaishi-119-february-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002797；EPUB电子本，纸本及异文待核", "id": "e2bafe52-b363-596e-9084-669d6ccb5d1e"}, {"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/jiuwudaishi-119-january-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002796；EPUB电子本，纸本及异文待核", "id": "bf14519c-5249-5e33-92a6-0deb16b4666b"}, {"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/jiuwudaishi-119-march-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002798；EPUB电子本，纸本及异文待核", "id": "70e7c49f-699d-570e-a3eb-c0c0e559fb77"}, {"title": "旧五代史·卷一百二十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/jiuwudaishi-128-wangpu-death/source.txt", "note": "《旧五代史》卷一百二十八，段落 jiu-wudaishi-205deb4a7860-p002983；EPUB电子本，纸本及异文待核", "id": "9f9afe05-816a-509b-893b-4b57e420b197"}, {"title": "旧五代史·卷一百四十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d5