INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "安审琦妾（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦受宠的妾，姓名未载。与仆人安友进私通，因怕事情泄露而提出谋杀安审琦，并威胁向安审琦告发安友进。谋划的具体日期未载。", "biography": null, "status": "draft", "id": "c75ec8f6-6b1b-5a07-8dd3-5923d6759435"}, {"name": "安友进", "aliases": ["安友進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦的仆人。与安审琦受宠的妾私通，受到告发威胁后同意谋杀安审琦。谋划记于958年末，实施在959年正月，二者分别录入。生卒年本段未载。", "biography": null, "status": "draft", "id": "2a4711e7-4ef4-595e-8398-f348d7b750da"}, {"name": "安万合", "aliases": ["安萬合"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦的部曲。《旧五代史》记959年正月七日夜，安友进不敢下手，召同党安万合杀死安审琦。数日后凶手事败，被安守忠处死。与安友进分别保存，生卒年未载。", "biography": null, "status": "draft", "id": "3161ec8c-21e2-5fee-a52f-81db41500d11"}, {"name": "安守忠", "aliases": ["安守忠（安审琦子）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字信臣，并州晋阳人，安审琦的儿子。959年正月父亲遇害数日后，他得知此事，抓获安友进等并处死。《宋史》本传记其早年随父任职、奉使淮南等经历。生卒年本段未核。", "biography": null, "status": "draft", "id": "b5d6f102-7093-58ff-b1bf-1d20be375fbd"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "窦俨", "aliases": ["竇儼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "窦仪的弟弟，后周中书舍人。957年九月上疏建议编修礼乐、改善官员选拔、治盗与劝农等。《宋史》还记其治理六纲奏疏和考正雅乐经历，各条未明确的日期保留未知。生卒年未载。", "biography": null, "status": "draft", "id": "db93a2b0-a248-5d82-b836-c6c907b158ff"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "殷盈孙", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：殷盈孙。", "biography": null, "status": "draft", "id": "77909eb6-6a7c-51e3-90aa-a88cd3bbd017"}, {"name": "萧承训", "aliases": ["蕭承訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "处士。《资治通鉴》所引王朴奏疏称其校定石磬，《旧五代史》乐志也载此事。属于雅乐修复历史的追述，具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "d15af053-fcb6-53db-a4df-d29c3b4b5a68"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "吴廷祚", "aliases": ["吳廷祚", "吴延祚", "吳延祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字庆之，并州太原人，早年为郭威亲校。959年二月以宣徽南院使身份与韩通督发丁夫浚汴水。新旧《五代史》又作吴延祚，按相同使职与留守任务关联，保留姓名异文。生卒年本段未核。", "biography": null, "status": "draft", "id": "8bc98a15-7a90-5881-b0f2-dd8e47a9d791"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "袁彦", "aliases": ["袁彥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河中河东人，后周步军都指挥使。959年二月奉命浚五丈渠，通往青州、郓州的漕运。《宋史》记其早年在郭威、柴荣麾下任职及参加寿州战事。与后蜀袁彦超分别保存，生卒年未核。", "biography": null, "status": "draft", "id": "60fe7e41-92bb-5b3e-9945-c4547bc3062f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
